    """Fill single background cells between matching foreground cells in each row."""
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foregrounds = [v for v in counts if v != background]
    if not foregrounds:
        return out
    foreground = max(foregrounds, key=lambda v: counts[v])
    for row in out:
        for c in range(1, len(row) - 1):
            if row[c] == background and row[c - 1] == foreground and row[c + 1] == foreground:
